/* 🧭 CLASSIFICAR RESULTADO & MONTAR MENSAGEM - RECEPTOR WEBHOOK (PADRÃO OFICIAL POLLER) */
const r = $json; // Saída do subworkflow Ferramenta Fiserv
let lead = {};
try {
  lead = $('Buscar Lead no DB').first().json;
} catch (e) {
  lead = {};
}

// 1. Extração robusta de status
const status = String(r.status || (r.data && r.data.status) || '').toLowerCase();
const externalStatus = String(r.external_status || r.data?.external_status || '');
const extLower = externalStatus.toLowerCase();

// DEFINIÇÃO CORRETA DE STATUS FINAIS (Idêntico ao Poller)
const APPROVED_FINAL = ['approved', 'pre_approved', 'comite_approved'];
const DENIED_FINAL   = ['denied', 'fails_to_process', 'lost', 'cancelled'];
const FORMALIZATION  = ['formalization'];
const WON_FINAL      = ['won'];
const FAIL_CONTACT   = ['fail_to_contact'];

let outcome = 'pending';

// 2. Extração de ofertas
const offerData = r.offer_data || r.data?.offer_data || null;

// Classificação: Se aprovado ou pré-aprovado pela Fiserv, é uma oferta!
if (APPROVED_FINAL.includes(status) || extLower.includes('aprovado') || extLower.includes('proposta')) {
    outcome = 'offer';
} else if (DENIED_FINAL.includes(status) || extLower.includes('reprovad')) {
    outcome = 'rejected';
} else if (FORMALIZATION.includes(status) || extLower.includes('formaliz')) {
    outcome = 'formalization';
} else if (FAIL_CONTACT.includes(status)) {
    outcome = 'fail_to_contact';
} else if (WON_FINAL.includes(status)) {
    outcome = 'won';
} else {
    outcome = 'pending';
}

const currentMetadata = lead.metadata || {};
const alreadySent = currentMetadata.fiserv_offer_sent === true || currentMetadata.fiserv_offer_sent === 'true';
const name = lead.name || 'Parceiro';
let message = '';

// 3. Montagem da Mensagem (Padronizada com o Poller)
if (outcome === 'offer' && !alreadySent) {
  const amount = offerData?.SomaPrincipal || r.data?.amount || r.amount || currentMetadata.requested_amount || '';
  const term   = offerData?.installments  || r.data?.installments || '24';
  const tax    = offerData?.PercJurosMensal || '';
  const amountFmt = amount ? Number(amount).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
  const reqAmount = parseFloat(currentMetadata.requested_amount || 0);
  const maxApproved = parseFloat(amount || 0);
  const maxTerm = term || 24;

  let ctaMessage = `👉 *Quer simular agora?* Me diga o valor que precisa e em quantas parcelas (de 6 a ${maxTerm} parcelas)!`;
  if (reqAmount > 0) {
    if (maxApproved > 0 && reqAmount > maxApproved) {
      ctaMessage = `O valor de *R$ ${reqAmount.toLocaleString('pt-BR')}* que você solicitou excede o seu limite pré-aprovado de *R$ ${amountFmt}*.\n\n👉 *Por favor, informe qual valor deseja solicitar (até R$ ${amountFmt}) e em quantas parcelas (de 6 a ${maxTerm} parcelas)!*`;
    } else {
      ctaMessage = `Entendi que você deseja simular o valor de *R$ ${reqAmount.toLocaleString('pt-BR')}*.\n\n👉 *Em quantas parcelas você gostaria de simular? (Lembrando que o prazo é de 6 a ${maxTerm} parcelas).*`;
    }
  }

  message = `🎉 *Boa notícia, ${name}!*\n\n` +
    `A análise do seu CNPJ foi concluída e você tem crédito pré-aprovado!\n\n` +
    (amountFmt ? `💰 *Limite aprovado:* R$ ${amountFmt}\n` : '') +
    (term  ? `📅 *Prazo:* até ${term} parcelas\n` : '') +
    (tax   ? `📉 *Taxa:* ${tax}% a.m.\n\n` : '\n') +
    `Você pode simular diferentes valores e prazos (de 6 a ${maxTerm} meses) dentro do seu limite aprovado.\n\n` +
    ctaMessage;

} else if (outcome === 'rejected' && !alreadySent) {
  message = `Olá, *${name}*!\n\n` +
    `Após a avaliação do comitê Fiserv, infelizmente não conseguimos liberar uma oferta de crédito para o seu CNPJ neste momento.\n\n` +
    `📋 *Motivo:* análise de crédito\n\n` +
    `Isso não é definitivo! Você pode tentar novamente em *30 dias*.\n\n` +
    `Central de Atendimento: *4004-2233*\n\n` +
    `Obrigado pela confiança na Ticket! 🙏`;

} else if (outcome === 'fail_to_contact' && !alreadySent) {
  message = `Olá, *${name}*!\n\nA nossa mesa de crédito tentou entrar em contato com você por telefone para prosseguir com a análise, mas infelizmente não conseguiu. 😕\n\n👉 *Qual é o melhor telefone e horário para nossa equipe te ligar?*`;

} else if (outcome === 'formalization' && !alreadySent) {
  message = `Olá, *${name}*! Excelente notícia!\n\n` +
    `Sua proposta de crédito foi *100% aprovada* e está agora na fase final de Assinatura e Formalização! 🎉\n\n` +
    `Fique de olho no seu e-mail e nos seus canais de contato para assinar o contrato digital. Qualquer dúvida, é só chamar!`;

} else if (outcome === 'won' && !alreadySent) {
  message = `Parabéns, *${name}*! 🚀\n\n` +
    `Seu crédito foi liberado com sucesso e o dinheiro já deve estar disponível na sua conta!\n\n` +
    `Agradecemos por escolher a Ticket e a Fiserv para turbinar o seu negócio. Caso precise de mais alguma coisa no futuro, é só me chamar aqui!`;
}

const decided = message !== '';

return [{
  json: {
    lead_id: lead.id,
    tenant_id: lead.tenant_id,
    agent_id: lead.agent_id,
    campaign_id: lead.campaign_id,
    cnpj: lead.cnpj,
    contact_name: name,
    contact_phone: lead.phone,
    loan_request_id: r.loan_request_id || lead.metadata?.loan_request_id,
    status,
    external_status: externalStatus,
    offer_data: offerData,
    outcome,
    decided: decided,
    message_content: message
  }
}];
